<?php declare(strict_types=1); namespace Codejitsu\Ai\Console; use Codejitsu\Console\TerminalQuestioner;
final class TerminalModelSetupIO implements ModelSetupIO { private TerminalQuestioner $q;public function __construct(?TerminalQuestioner $q=null){$this->q=$q??new TerminalQuestioner();}public function select(string $question,array $choices):string{return $this->q->select($question,$choices);}public function ask(string $question,string $default=''):string{return $this->q->ask($question,$default);}public function confirm(string $question):bool{return in_array(strtolower($this->q->ask($question.' [y/N] ')),['y','yes'],true);}public function write(string $message):void{fwrite(STDOUT,$message);} }
